sys_script_fix.script:
var scopeName = gs.getCurrentScopeName();
var scopeGQ = new global.GlideQuery('sys_store_app').getBy({ scope: scopeName }).orElse({ sys_id: null });

function groupHasPkiUserRole(userGroupName) {
	var userRoleName = 'sn_disco_certmgmt.pki_user';
	var grUserRole = new GlideRecord('sys_user_role');
	if (!grUserRole.get('name', userRoleName)) {
		throw Error("Role " + userRoleName + " não encontrada");
	}

	var grUserGroup = new GlideRecord('sys_user_group');
	if (!grUserGroup.get('name', userGroupName)) {
		throw Error("Grupo de usuários não existe: " + userGroupName);
	}

	var grGroupHasRole = new GlideRecord('sys_group_has_role');
	grGroupHasRole.addQuery('group', grUserGroup.sys_id);
	grGroupHasRole.addQuery('role', grUserRole.sys_id);
	grGroupHasRole.query();
	if (!grGroupHasRole.next()) {
		new global.GlideQuery('sys_group_has_role')
			.insert({ group: grUserGroup.sys_id, role: grUserRole.sys_id });
		gs.info("Criando Role " + grUserRole.name + ' no grupo ' + grUserGroup.name);
	}
}

// criar as propriedades que inibem a renovação automatica de certificados
function setProps() {
	logInfo('Criação / Atualização de Propriedades - Inicio.');
	var properties = [
		{ type: 'string', check: groupHasPkiUserRole, name: "BNB_certificados_internos", value: "INFRA - Linux" },
		{ type: 'string', check: groupHasPkiUserRole, name: "BNB_instalacao_certificados", value: "INFRA - Linux" },
		{ type: 'string', check: groupHasPkiUserRole, name: "BNB_instalacao_certificados_Windows", value: "INFRA - Windows" },
		{ type: 'string', check: groupHasPkiUserRole, name: "BNB_certificados_externos", value: "SEGURANÇA - Funcionários da CSI" },
		{ type: 'boolean', name: 'auto_renew.internal_certificates', value: 'true' },
		{ type: 'boolean', name: 'auto_renew.external_certificates', value: 'true' }
	];

	properties.forEach(function (prop) {
		var propName = scopeName + '.' + prop.name;
		if (prop.check) {
			prop.check(prop.value);
		}
		var propGQ = new global.GlideQuery('sys_properties')
			.getBy({ sys_scope: scopeGQ.sys_id, name: propName })
			.orElse({ sys_id: null });

		var newProp = new global.GlideQuery('sys_properties')
			.insertOrUpdate({
				sys_id: propGQ.sys_id,
				sys_scope: scopeGQ.sys_id,
				name: propName,
				value: prop.value,
				type: prop.type
			})
			.orElse({ sys_id: null });
		logInfo('Configurada propriedade: ' + prop.name + '=' + prop.value);
	});
	logInfo('Criação / Atualização de Propriedades - Fim.');
}

function setMid() {
	logInfo('Ajuste MID Server Cluster - Inicio.');
	// Ajusta MID Server do discovery schedule
	var clusterName = 'MID_CAPGV_COM';
	var grMID = new global.GlideQuery('ecc_agent_cluster')
		.getBy({ name: clusterName })
		.orElse({ sys_id: null });

	if (!grMID.sys_id) {
		throw Error("Cluster " + clusterName + ' Not found in environment');
	}

	var grDisco = new global.GlideQuery('discovery_schedule')
		.where("sys_scope.scope", scopeName)
		.select('sys_id', 'name')
		.forEach(function (sch) {
			new global.GlideQuery('discovery_schedule')
				.where("sys_id", sch.sys_id)
				.update({ mid_select_method: "specific_cluster", mid_cluster: grMID.sys_id });
			logInfo('Updated Mid Cluster for Discovery Schedule ' + sch.name);
		});
	logInfo('Ajuste MID Server Cluster - Fim.');
}

function setAWXCredential() {
	logInfo('Ajuste Credencial Ansible - Inicio.');
	var key = "zV74yRf8HoUDqLXmO1PLP5vmXvHU24";
	var credGQ = new GlideRecord('api_key_credentials');
	credGQ.addQuery("name", "AWX API Key");
	credGQ.query();
	if (!credGQ.next()) throw Error("Missing [AWX API Key] record in table api_key_credentials");

	var cred = new sn_cc.StandardCredentialsProvider().getCredentialByID(credGQ.sys_id);
	var token = cred.getAttribute('api_key') || '';
	if (token != key) {
		var baseURL = gs.getProperty("instance_name") + '.service-now.com/now/nav/ui/classic/params/target/';
		throw Error("Verifique Token AWX em \n" + baseURL + credGQ.getLink());
	}
	logInfo('Ajuste Credencial Ansible - Fim.');
}

function updateMetadata() {
	logInfo("Atualização de Certificate Metadata - Inicio.");
	var utils = new sn_disco_certmgmt.BNBCertificateMangementUtils();
	utils.updatedAllCertsMetadata();
	logInfo("Atualização de Certificate Metadata - Fim.");
}

function setMidCluster() {
	var clusterByInsance = {
		bnbdev: "MID_CAPGV_COM",
		bnbhom: "MID_CAPGV_COM",
		bnbprod: "MID_CAPGV_DIS",
	};
	var midClusterName = clusterByInsance[gs.getProperty("instance_name")];
	var midCluster = new global.GlideQuery("ecc_agent_cluster")
		.getBy({
			name: midClusterName
		}, ["sys_id", "name"])
		.orElse({
			sys_id: "",
			name: ''
		}).sys_id;

	new global.GlideQuery("discovery_schedule")
		.where('sys_scope.name', "Certificate Inventory and Management")
		.where('mid_select_method', 'specific_cluster')
		.select("name")
		.forEach(function (disc) {
			new global.GlideQuery("discovery_schedule")
				.where("sys_id", disc.sys_id)
				.update({
					mid_cluster: midCluster
				});
		});

	var D001ACP02gr = new GlideRecord("cmdb_ci_win_server");
	if (!D001ACP02gr.get('name', 'D001ACP02')) {
		throw Error("Missing Windows Server for Microsoft CA: d001acp03");
	}
	var d001acp03gr = new GlideRecord("cmdb_ci_win_server");
	if (!d001acp03gr.get('name', 'd001acp03')) {
		throw Error("Missing Windows Server for Microsoft CA: d001acp03");
	}

	[{
		ip: '200.164.107.13',
		proxy: d001acp03gr
	},
	{
		ip: '128.15.1.242',
		proxy: D001ACP02gr
	},
	].forEach(function (ipProxy) {
		new global.GlideQuery("discovery_ptrn_lnch_param")
			.where('sys_scope.name', 'Certificate Inventory and Management')
			.where('param.key', 'ip')
			.where('value', ipProxy.ip)
			.select(["pattern_launcher"])
			.forEach(function (lnch) {
				var lnchr = new global.GlideQuery("discovery_ptrn_hostless_lchr")
					.get(lnch.pattern_launcher, ["name"])
					.orElse({
						name: "Não Encontrou"
					});
				gs.info(JSON.stringify(lnchr));
				new global.GlideQuery("discovery_ptrn_hostless_lchr")
					.where("sys_id", lnch.pattern_launcher)
					.update({
						cmdb_ci: ipProxy.proxy.sys_id
					});
			});
	});
}

function logInfo(ex) { gs.info("EDX - Customização certificados - " + ex); }

function logError(ex) { gs.error("EDX - Customização certificados - " + ex); }

var failures = [];
// try { setProps(); } catch (ex) {
// 	failures.push(ex);
// }

// try { setMid(); } catch (ex) {
// 	failures.push(ex);
// }

try { setAWXCredential(); } catch (ex) {
	failures.push(ex);
}

// try { updateMetadata(); } catch (ex) {
// 	failures.push(ex);
// }

try { setMidCluster(); } catch (ex) {
	failures.push(ex);
}

if (failures.length + 0) {
	failures.forEach(function (ex) { logError(ex); });
	throw Error("\nFix script falhou:\n  ##### " + failures.join('\n  ##### '));
}
